"""寫出前把詳細表的 itemKey 換成 PCCES 匯入時會編的號碼，公式裡的引用一起換（PCX-002）。

PCCES 匯入 `applicationName` 不是 Pcces 的 XML 時，不管 itemKey 是多少，詳細表每列的 `budItemA.sNo`
一律依先序走訪重編成 1..N（總計列排最後）。公式 Amount 段的引用（`budItemB`）有跟著換成新號，
自訂變數定義段的引用（`BudPCalsCustomVar.SNo`）卻照抄 XML 的數字，重新總計時就算到別列
（資料庫 ArchEx001-04、Class01-02 實測）。寫出器標的是本工具名，所以一律先編成那個號碼，
兩段引用匯入後才都指對列；已經是這個號碼的文件原樣不動。

只動詳細表：資源統計 PayItem 的 itemKey 與單價分析的 refItemNo 放的是項次，不是 sNo（對照文件 2.2、2.3）。
小計列也照先序編：實案改成本工具名再匯入，3721 列連中間 217 列小計全照先序重編，
公式引用小計列的 budItemB 也跟著換（161→3716），所以引用中間小計列照新號換（PCX-003）。
只有頂層最後那列總計保留原 itemKey（PCCES 匯出檔固定 999999），PCCES 匯入時照樣把它編成 N。
"""

from __future__ import annotations

import copy
import dataclasses
import re

from .document import ETenderDocument, Item, Node
from .etender import item_path

SUBTOTAL_KIND = "subtotal"
MATHML_NS = "http://www.w3.org/1998/Math/MathML"
MATH_TAG = "mml:math"
CI_TAG = "mml:ci"
# ci 裡全是數字才是引用列；VAR1、Percent、Amount、VAR1Percent 這些是變數名
_REF = re.compile(r"\s*(\d+)\s*")


def _kind(it: Item) -> str:
    return it.attrs.get("itemKind", "").strip()


def _label(path: list[Item]) -> str:
    no, parent_no = "", ""
    for i in path[:-1]:
        own = i.attrs.get("itemNo", "").strip()
        no, parent_no = item_path(no, parent_no, own), own
    name = (path[-1].value("Description", "zh-TW") or "").strip()
    own = path[-1].attrs.get("itemNo", "").strip()
    if not own:  # 小計列沒有項次
        return f"{no or '頂層'} 底下的「{name}」"
    return f"{item_path(no, parent_no, own)} {name}"


def _walk(items: list[Item], chain: list[Item]):
    for it in items:
        yield chain + [it]
        yield from _walk(it.children, chain + [it])


def _key_int(key: str) -> int | None:
    k = key.strip()
    return int(k) if k.isdigit() else None


def _check_prefix(doc: ETenderDocument, paths: list[list[Item]]) -> None:
    """公式只認 `mml:` 前綴；別的前綴會讓引用漏換而不自知，寧可拒寫。"""
    other = [k for k, v in doc.root_attrs.items() if v == MATHML_NS and k != "xmlns:mml"]
    if other:
        raise ValueError(f"MathML 宣告成 {other[0]}，不是 PCCES 用的 xmlns:mml，公式引用沒辦法跟著 itemKey 重編")
    for path in paths:
        for f in path[-1].fields:
            if f.tag != MATH_TAG and (f.tag == "math" or f.tag.endswith(":math")):
                raise ValueError(f"{_label(path)} 的公式是 <{f.tag}>，不是 <{MATH_TAG}>，引用沒辦法跟著 itemKey 重編")


def _grand_total(items: list[Item]) -> Item | None:
    """頂層最後那列是小計才算總計列；中間的小計列不算。"""
    return items[-1] if items and _kind(items[-1]) == SUBTOTAL_KIND else None


def _ci_nodes(n: Node):
    if n.tag == CI_TAG:
        yield n
    for c in n.children:
        yield from _ci_nodes(c)


def renumber_item_keys(doc: ETenderDocument) -> ETenderDocument:
    """回傳 itemKey 依先序重編、公式引用跟著換的文件；`doc` 本身不動，詳細表以外的節點共用。

    公式引用了詳細表沒有的 itemKey、重複的 itemKey 或頂層總計列時丟 ValueError：那種引用重編後指到哪列沒有依據。
    中間的小計列跟一般列一樣照先序編號，引用它的公式照新號換。
    """
    dl = copy.deepcopy(doc.detail_list)
    paths = list(_walk(dl.items, []))
    _check_prefix(doc, paths)

    new: dict[int, str] = {id(p[-1]): str(n) for n, p in enumerate(paths, 1)}
    total = _grand_total(dl.items)
    if total is not None:
        key = total.attrs.get("itemKey", "").strip()
        # 原號跟別列的新號撞到就不保留，跟著編成 N
        if key and key not in {v for k, v in new.items() if k != id(total)}:
            new[id(total)] = total.attrs["itemKey"]

    by_old: dict[int, list[list[Item]]] = {}
    for p in paths:
        k = _key_int(p[-1].attrs.get("itemKey", ""))
        if k is not None:
            by_old.setdefault(k, []).append(p)

    for p in paths:
        for f in p[-1].fields:
            if f.tag != MATH_TAG:
                continue
            for ci in _ci_nodes(f):
                m = _REF.fullmatch(ci.text or "")
                if not m:
                    continue
                hits = by_old.get(int(m.group(1)), [])
                if not hits:
                    raise ValueError(f"{_label(p)} 的公式引用 itemKey {m.group(1)}，詳細表沒有這一列，重編後不知道該指到哪列")
                if len(hits) > 1:
                    raise ValueError(f"{_label(p)} 的公式引用 itemKey {m.group(1)}，詳細表有 {len(hits)} 列用這個號碼，分不出指哪列")
                target = hits[0][-1]
                if target is total:
                    raise ValueError(
                        f"{_label(p)} 的公式引用頂層總計列，ArchEx001、Class01、實案都沒有這種引用，PCCES 匯入後怎麼對應沒有依據"
                    )
                ci.text = ci.text[: m.start(1)] + new[id(target)] + ci.text[m.end(1):]

    for p in paths:
        it = p[-1]
        if "itemKey" in it.attrs:
            it.attrs["itemKey"] = new[id(it)]
        else:
            # 交換標準 itemKey 必填；沒有就補在最前面（PCCES 匯出檔的位置）
            it.attrs = {"itemKey": new[id(it)], **it.attrs}
    return dataclasses.replace(doc, detail_list=dl)
